Example: Manager and Grade Classes: class Manager {
    class Grade {  // Inner class
        private char grade;
        public char calculateGrade(String employeeID, int point) {
            // Calculate grade
            return grade;
        }
    }

    public char checkEmployeeID(String employeeId, int point) {
        Grade grade = new Grade();  // Inner class instantiated inside outer class
        return grade.calculateGrade(employeeId, point);
    }
}

Accessing Inner Class from Outside:  class Feedback {
    public static void main(String[] args) {
        Manager manager = new Manager();
        Manager.Grade grade = manager.new Grade();  // Accessing inner class outside
        grade.calculateGrade("Emp-001", 65);
    }
}

Private Inner Class Example:  class Manager {
    private class Grade {  // Private inner class
        private char grade;
        public char calculateGrade(String employeeID, int point) {
            return grade;
        }
    }

    public char checkEmployeeID(String employeeId, int point) {
        Grade grade = new Grade();
        return grade.calculateGrade(employeeId, point);
    }
}

Syntax Example: An anonymous inner class that implements an interface: interface Grade {
    char calculateGrade(String employeeID, int point);
}

class Manager {
    Grade grade = new Grade() {  // Anonymous inner class implementing the interface
        private char grade;
        public char calculateGrade(String employeeID, int point) {
            return grade;
        }
    };

    public char checkEmployeeID(String employeeId, int point) {
        return grade.calculateGrade(employeeId, point);
    }
}

Example with Class Inheritance: An anonymous class can extend a class and override its methods: class Grade {
    private char grades;
    public char calculateGrade(String employeeID, int point) {
        return grades;
    }
}

class Manager {
    Grade grade = new Grade() {  // Anonymous class extending Grade
        private char grade;
        public char calculateGrade(String employeeID, int point) {
            return grade;
        }
    };

    public char checkEmployeeID(String employeeId, int point) {
        return grade.calculateGrade(employeeId, point);
    }
}

